package com.example.leetcodetrainer.coaching.service;
import com.example.leetcodetrainer.attempt.domain.*; import com.example.leetcodetrainer.attempt.repository.*; import com.example.leetcodetrainer.coaching.domain.*; import com.example.leetcodetrainer.coaching.repository.*; import com.example.leetcodetrainer.failure.service.*; import com.example.leetcodetrainer.hint.service.HintService; import java.time.*; import java.util.*; import org.springframework.context.event.EventListener; import org.springframework.core.annotation.Order; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @Transactional public class CoachingService { private final AttemptRepository attempts; private final StageAssessmentRepository stages; private final HintService hints; private final FailureLabelService failures; private final CoachProvider provider; private final CoachingMessageRepository messages; private final Clock clock;
 public CoachingService(AttemptRepository a,StageAssessmentRepository s,HintService h,FailureLabelService f,CoachProvider p,CoachingMessageRepository m,Clock c){attempts=a;stages=s;hints=h;failures=f;provider=p;messages=m;clock=c;}
 @EventListener @Order(2) public void onComplete(AttemptCompletedEvent e){generate(e.attemptId());} public CoachingMessage generate(UUID id){Attempt a=attempts.findById(id).orElseThrow();List<StageAssessment> ss=stages.findByAttemptIdOrderByStageTypeAsc(id);Map<StageType,Integer> levels=new EnumMap<>(StageType.class);for(StageAssessment s:ss)levels.put(s.getStageType(),hints.maxHintLevel(id,s.getStageType()));CoachingContext c=new CoachingContext(a,ss,levels,failures.analysis(id),attempts.findByProblemIdOrderByStartedAtDesc(a.getProblemId()));return messages.save(new CoachingMessage(UUID.randomUUID(),id,provider.name(),provider.version(),provider.generate(c),Instant.now(clock)));} @Transactional(readOnly=true) public CoachingMessage latest(UUID id){return messages.findByAttemptIdOrderByGeneratedAtDesc(id).stream().findFirst().orElse(null);} }
